(function(){
const root=document.querySelector('#additionalComponents');
const icon=(src,alt='')=>`<img src="assets/${src}" alt="${alt}">`;
const block=(name,source,html,cls='')=>`<div class="showcase-component exact-component ${cls}"><span class="component-label">${name}</span><small class="exact-source">Источник: ${source}</small>${html}</div>`;
const days=Array.from({length:31},(_,i)=>{const d=i+1,cls=d===20?'range-start':d===21?'range-end':d>20&&d<21?'in-range':d%7>4?'weekend':'';return `<button class="${cls}"><span>${d}</span></button>`}).join('');
const pageTitle=block('PageTitle','Заказы, Контакты, Платежи',`<section class="exact-titlebar"><div>Заказы</div></section>`);
const backTitle=block('BackPageTitle','Страница заказа',`<a class="exact-back-title" href="orders.html">${icon('arrow-right-xs-16.svg')}<span>Заказ 87654321</span></a>`);
const calendar=block('DateRangePicker','Заказы и платёжные документы',`<div class="exact-calendar"><div class="exact-calendar-months">${['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'].map((m,i)=>`<button class="${i===11?'selected':''}">${m}</button>`).join('')}</div><div class="exact-calendar-main"><div class="exact-calendar-week"><span>пн</span><span>вт</span><span>ср</span><span>чт</span><span>пт</span><span class="weekend">сб</span><span class="weekend">вс</span></div><b>Декабрь 2026</b><div class="exact-calendar-days">${'<i></i>'.repeat(1)}${days}</div></div></div>`,'exact-calendar-wrap');
const guestPicker=block('GuestPicker','Главная страница',`<div class="exact-guests"><div class="exact-guest-row"><span><b>Взрослые</b><small>От 18 лет</small></span><div class="exact-stepper"><button>−</button><output>1</output><button>+</button></div></div><div class="exact-guest-row"><span><b>Дети</b><small>До 17 лет</small></span><div class="exact-stepper"><button>−</button><output>0</output><button>+</button></div></div><div class="exact-guest-row"><span><b>Номера</b></span><div class="exact-stepper"><button>−</button><output>1</output><button>+</button></div></div></div>`,'exact-guests-wrap');
const stepper=block('CounterStepper','Выбор гостей',`<div class="exact-stepper"><button>−</button><output>2</output><button>+</button></div>`,'exact-stepper-wrap');
const select=block('SelectDropdown','Список заказов',`<div class="exact-select"><button><span>Предстоящие</span>${icon('arrow-down-fill-16.svg')}</button><div><button class="selected">Предстоящие</button><button>Прошедшие</button><button>Все заказы</button></div></div>`,'exact-select-wrap');
const dataTable=block('DataTable','Платёжные документы',`<div class="exact-table"><div class="exact-table-row head"><span>Номер</span><span>Дата</span><span>Сумма, ₽</span><span>НДС, ₽</span><span>Назначение платежа</span></div><div class="exact-table-row"><span>12600031</span><span>9 сен 2026</span><span>105 000 ₽</span><span>20 000 ₽</span><span>Оплата услуг размещения по заказу</span></div><div class="exact-table-row"><span>12600030</span><span>8 сен 2026</span><span>74 500 ₽</span><span>14 900 ₽</span><span>Оплата услуг размещения по договору</span></div></div>`);
const tableRow=block('TableRow','График платежей',`<div class="exact-payment-row"><span>20 дек 2026</span><span>126 500 ₽</span><span>25 300 ₽</span><span>151 800 ₽</span></div>`);
const columns=block('ColumnSettingsPanel','Платежи и платёжные документы',`<aside class="exact-columns"><button class="exact-close">${icon('profile-close-24.svg')}</button><h2>Настройка столбцов</h2><p>Выберите столбцы и измените их порядок</p><div>${['Дата платежа','Сумма платежа','Сумма НДС','Назначение платежа'].map((x,i)=>`<label><input type="checkbox" ${i<3?'checked':''}><span>${x}</span>${icon('sorting-default-20.svg','Перетащить')}</label>`).join('')}</div><button class="exact-save">Сохранить</button></aside>`,'exact-columns-wrap');
const toast=block('Toast','Шесть страниц прототипа',`<div class="exact-toast">Фильтры применены</div>`,'exact-toast-wrap');
const modal=block('ConfirmModal','Страница подборок',`<section class="exact-modal"><button class="exact-modal-close">${icon('profile-close-24.svg')}</button><h2>Удаление подборки</h2><p>Это действие нельзя отменить.<br>Вы уверены, что хотите продолжить?</p><div><button>Не удалять</button><button class="danger">Удалить</button></div></section>`,'exact-modal-wrap');
const event=block('EventCard','Главная страница',`<article class="exact-event"><img src="assets/home/event-new-2.png" alt=""><div><time>18.08.2026</time><h3>Улучшаем качество обслуживания: запущена отдельная линия поддержки</h3></div>${icon('home/figma-8422/arrow-long-right.svg')}</article>`,'exact-event-wrap');
const destination=block('DestinationCard','Главная страница',`<article class="exact-destination"><img src="assets/home/international-istanbul.png" alt="Стамбул"><h3>Стамбул</h3><p>от 12 000 ₽</p></article>`,'exact-destination-wrap');
const collection=block('CollectionRow','Страница подборок',`<article class="exact-collection"><div><div>Город Москва, Россия, 20 дек — 21 дек 2026</div><span>1 ночь · 1 взрослый</span></div><time>1 окт 2026</time><button>${icon('collections/trash.svg','Удалить')}</button></article>`);
const history=block('HistoryRow','История заказа',`<div class="exact-history"><div>13 июл 2026, 11:07<br>ООО «АОН.РУ»</div><div>Новое уведомление создано<small>63166005</small></div><div><button>${icon('profile-document-24.svg')}Скачать документ</button></div></div>`);
root.insertAdjacentHTML('beforeend',`<section class="showcase-section"><div class="showcase-heading showcase-heading--stack"><h2>Дополнительные повторяющиеся компоненты</h2><p>Перенесены из существующих экранов вместе с исходными состояниями.</p></div><div class="demo-list">${pageTitle+backTitle+calendar+guestPicker+stepper+select+dataTable+tableRow+columns+event+destination}</div></section>`);
})();
